{
  "edges": {
    "Triggers__Maladaptive_Strategies": {
      "weight": 8,
      "explanation": "The vignette says reminders are actively managed and that she avoids situations that remind her of the trauma.",
      "quote": "“Related media content, talking about the event, and seeing people who resemble the victims are reminders she tries hard to manage.”"
    },
    "Triggers__Threat": {
      "weight": 8,
      "explanation": "Reminders are described alongside a fragile sense of safety and constant watchfulness, implying they reactivate current danger.",
      "quote": "“Related media content... are reminders... Her sense of safety has been fragile, and she describes living in a state of constant watchfulness.”"
    },
    "Triggers__Memory": {
      "weight": 8,
      "explanation": "The vignette links reminders such as media, talking, and resemblance cues to the trauma memory being reactivated.",
      "quote": "“Related media content, talking about the event, and seeing people who resemble the victims are reminders”"
    },
    "Triggers__Negative_Appraisals": {
      "weight": 4,
      "explanation": "Triggers and painful beliefs are both present, but the vignette does not directly show the reminders causing the beliefs.",
      "quote": "“Related media content... are reminders”"
    },
    "Negative_Appraisals__Maladaptive_Strategies": {
      "weight": 6,
      "explanation": "Her painful beliefs are described alongside extensive avoidance and numbing, suggesting these appraisals help maintain her coping strategies.",
      "quote": "“Alongside this, she holds painful beliefs... In response, she keeps her mind occupied all the time, numbs her emotions, avoids other people”"
    },
    "Negative_Appraisals__Threat": {
      "weight": 8,
      "explanation": "Her beliefs that she cannot stop bad things and does not know herself are presented as part of her ongoing sense of unsafe current danger.",
      "quote": "“she holds painful beliefs... worries that she cannot stop bad things from happening to her”"
    },
    "Negative_Appraisals__Memory": {
      "weight": 2,
      "explanation": "The vignette places her painful beliefs near the trauma memory description, but does not indicate that the beliefs shape the memory itself.",
      "quote": "“The event itself is held in memory... Alongside this, she holds painful beliefs”"
    },
    "Negative_Appraisals__Triggers": {
      "weight": 2,
      "explanation": "The account mentions both beliefs and reminders, but it does not state that the beliefs generate the triggers.",
      "quote": "“Alongside this, she holds painful beliefs... Related media content... are reminders”"
    },
    "Memory__Maladaptive_Strategies": {
      "weight": 6,
      "explanation": "Her vivid trauma memory is followed by efforts to suppress and avoid reminders, suggesting the memory drives those strategies.",
      "quote": "“These vivid images remain central to her experience. Related media content... are reminders she tries hard to manage.”"
    },
    "Memory__Threat": {
      "weight": 6,
      "explanation": "The vivid fragmented memory is embedded in a broader state of watchfulness and fragility of safety, implying it sustains threat.",
      "quote": "“The event itself is held in memory in a fragmented but vividly detailed way... her sense of safety has been fragile”"
    },
    "Memory__Negative_Appraisals": {
      "weight": 6,
      "explanation": "The trauma memory is presented before and alongside the painful meanings she gives the event, suggesting the memory feeds those appraisals.",
      "quote": "“The event itself is held in memory... Alongside this, she holds painful beliefs about what the event means”"
    },
    "Memory__Triggers": {
      "weight": 8,
      "explanation": "The vignette explicitly states that related cues remind her of the event, showing the memory is activated by triggers.",
      "quote": "“Related media content, talking about the event, and seeing people who resemble the victims are reminders”"
    },
    "Threat__Maladaptive_Strategies": {
      "weight": 8,
      "explanation": "Her ongoing sense of threat is followed by constant mental occupation, emotional numbing, avoidance, and staying away from reminders.",
      "quote": "“her sense of safety has been fragile... In response, she keeps her mind occupied all the time, numbs her emotions, avoids other people”"
    },
    "Threat__Memory": {
      "weight": 4,
      "explanation": "Threat and trauma memory are both described, but the vignette does not clearly state that current threat causes the memory.",
      "quote": "“her sense of safety has been fragile... The event itself is held in memory”"
    },
    "Threat__Negative_Appraisals": {
      "weight": 6,
      "explanation": "Her persistent watchfulness and fragile safety sit alongside her painful interpretations of the event, suggesting threat is bound up with those appraisals.",
      "quote": "“living in a state of constant watchfulness... she holds painful beliefs about what the event means”"
    },
    "Threat__Triggers": {
      "weight": 2,
      "explanation": "Threat and reminders are both present, but the text does not explicitly say her sense of danger produces the triggers.",
      "quote": "“her sense of safety has been fragile... Related media content... are reminders”"
    },
    "Maladaptive_Strategies__Memory": {
      "weight": 4,
      "explanation": "She avoids and numbs, but the vignette does not directly show these strategies altering the trauma memory itself.",
      "quote": "“she keeps her mind occupied all the time, numbs her emotions, avoids other people”"
    },
    "Maladaptive_Strategies__Negative_Appraisals": {
      "weight": 4,
      "explanation": "The vignette links her avoidance and numbing to short-term relief and a narrowed life, but not directly to changes in her beliefs.",
      "quote": "“These efforts offer short-term relief, but they have narrowed her life”"
    }
  }
}
